const visual = {
  prepare: function (input) {
    var texts = [
      '单位换算表',
      '126 km/h 换算为 m/s（除以 3.6）',
      '换算项目',
      '换算算式',
      '换算结果',
      '126 km/h → m/s',
      '126 ÷ 3.6 = 35.0',
      '35.0 m/s',
      '结果保留三位有效数字'
    ];
    var req = [];
    for (var i = 0; i < texts.length; i++) {
      req.push({ kind: 'text', payload: texts[i] });
    }
    return req;
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = 24;
    var tableX = margin;
    var tableY = 96;
    var tableW = Math.min(W - margin * 2, 640);
    if (tableW < 320) {
      tableW = Math.max(280, W - margin * 2);
    }
    var col1 = Math.round(tableW * 0.28);
    var col2 = Math.round(tableW * 0.40);
    var col3 = tableW - col1 - col2;
    var headerH = 40;
    var rowH = 44;
    var tableH = headerH + rowH;

    var headerBg = visualSdk.polyline([
      [tableX, tableY],
      [tableX + tableW, tableY],
      [tableX + tableW, tableY + headerH],
      [tableX, tableY + headerH],
      [tableX, tableY]
    ]);

    var grid = [];
    grid = grid.concat(visualSdk.polyline([
      [tableX, tableY],
      [tableX + tableW, tableY],
      [tableX + tableW, tableY + tableH],
      [tableX, tableY + tableH],
      [tableX, tableY]
    ]));
    grid = grid.concat(visualSdk.polyline([[tableX + col1, tableY], [tableX + col1, tableY + tableH]]));
    grid = grid.concat(visualSdk.polyline([[tableX + col1 + col2, tableY], [tableX + col1 + col2, tableY + tableH]]));
    grid = grid.concat(visualSdk.polyline([[tableX, tableY + headerH], [tableX + tableW, tableY + headerH]]));

    var titleY = 42;
    var subtitleY = 72;
    var headerBaseline = tableY + 26;
    var dataBaseline = tableY + headerH + 27;
    var noteY = tableY + tableH + 30;

    var children = [];
    children.push({ type: 'path', pathId: 'headerBg', fill: '#eef3f8', stroke: 'none' });
    children.push({ type: 'path', pathId: 'grid', fill: 'none', stroke: '#26354a', strokeWidth: 1.5 });

    children.push({ type: 'label', x: margin, y: titleY, text: '单位换算表', fontSize: 22, fontWeight: 'bold', fill: '#1f2d3d' });
    children.push({ type: 'label', x: margin, y: subtitleY, text: '126 km/h 换算为 m/s（除以 3.6）', fontSize: 14, fill: '#44546a' });

    children.push({ type: 'label', x: tableX + 10, y: headerBaseline, text: '换算项目', fontSize: 15, fontWeight: 'bold', fill: '#26354a' });
    children.push({ type: 'label', x: tableX + col1 + 10, y: headerBaseline, text: '换算算式', fontSize: 15, fontWeight: 'bold', fill: '#26354a' });
    children.push({ type: 'label', x: tableX + col1 + col2 + 10, y: headerBaseline, text: '换算结果', fontSize: 15, fontWeight: 'bold', fill: '#26354a' });

    children.push({ type: 'label', x: tableX + 10, y: dataBaseline, text: '126 km/h → m/s', fontSize: 15, fill: '#1f2d3d' });
    children.push({ type: 'label', x: tableX + col1 + 10, y: dataBaseline, text: '126 ÷ 3.6 = 35.0', fontSize: 15, fill: '#1f2d3d' });
    children.push({ type: 'label', x: tableX + col1 + col2 + 10, y: dataBaseline, text: '35.0 m/s', fontSize: 15, fontWeight: 'bold', fill: '#1f2d3d' });

    children.push({ type: 'label', x: margin, y: noteY, text: '结果保留三位有效数字', fontSize: 13, fill: '#6b7a90' });

    return {
      schemaVersion: 1,
      sceneId: 'unit-conversion-table',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'headerBg', commands: headerBg },
        { id: 'grid', commands: grid }
      ],
      root: { type: 'group', children: children }
    };
  }
};
